//! Primitives: library introspection ((scm module) %load-module,
//! %module-exports, %module-ref) over the table of every library's exports
//! (library_exports.zig, generated by tools/gen-library-exports.scm), so
//! that (scm source) can tell what an import provides (scm lint, scm fmt)
//! also for libraries that are not linked into the program.
//!
//! %module-ref gives a stand-in of the binding's kind: a macro object for
//! syntax, a procedure that raises an error when called for procedures,
//! the unspecified value for other values (values themselves need eval).
const std = @import("std");
const rt = @import("rt.zig");
const data = @import("data.zig");
const printer = @import("printer.zig");
const sys = @import("prims_sys.zig");
const lib = @import("library_exports.zig");
const P = @import("prims.zig");
const Word = rt.Word;
const Thread = rt.Thread;
const Err = P.Err;
const WN = P.WN;
const arg = P.arg;
const raise = P.raise;

const pa = std.heap.c_allocator;

/// The library named by w: a list like (scheme base) or a string like
/// "scheme base"
fn findLibrary(w: Word) ?*const lib.Library {
    var b: std.ArrayList(u8) = .empty;
    defer b.deinit(pa);
    if (data.isString(w)) {
        b.append(pa, '(') catch rt.oom();
        b.appendSlice(pa, data.toUtf8(w)) catch rt.oom();
        b.append(pa, ')') catch rt.oom();
    } else printer.print(&b, w, true);
    for (&lib.libraries) |*l| if (std.mem.eql(u8, l.name, b.items)) return l;
    for (user_libraries.items) |l| if (std.mem.eql(u8, l.name, b.items)) return l;
    return null;
}

/// The program's libraries that library_exports.zig does not have (defined
/// in the program, or not in scm-lib), registered at startup
var user_libraries: std.ArrayList(*lib.Library) = .empty;

/// spec: the exports, each a kind letter (s syntax, u unknown) and the
/// name, separated by spaces
pub fn registerLibrary(name: []const u8, spec: []const u8) void {
    var exports: std.ArrayList(lib.Export) = .empty;
    var it = std.mem.tokenizeScalar(u8, spec, ' ');
    while (it.next()) |e| {
        exports.append(pa, .{ .name = e[1..], .kind = if (e[0] == 's') .syntax else .unknown, .id = 0 }) catch rt.oom();
    }
    const l = pa.create(lib.Library) catch rt.oom();
    l.* = .{ .name = name, .exports = exports.items };
    user_libraries.append(pa, l) catch rt.oom();
}

fn libraryArg(t: *Thread, who: []const u8) Err!*const lib.Library {
    return findLibrary(arg(t, 0)) orelse
        raise(t, std.fmt.allocPrint(pa, "{s}: module ~a not found", .{who}) catch rt.oom(), &.{arg(t, 0)});
}

fn loadModule(t: *Thread) Err!Word {
    _ = try libraryArg(t, "%load-module");
    return rt.TRUE;
}
pub const @"%%load-module" = WN("%load-module", loadModule, 1, 2);

/// the export names, sorted (as the JVM implementation)
fn moduleExports(t: *Thread) Err!Word {
    const l = try libraryArg(t, "%module-exports");
    var names: std.ArrayList([]const u8) = .empty;
    defer names.deinit(pa);
    for (l.exports) |e| names.append(pa, e.name) catch rt.oom();
    std.mem.sort([]const u8, names.items, {}, struct {
        fn lt(_: void, a: []const u8, b: []const u8) bool {
            return std.mem.order(u8, a, b) == .lt;
        }
    }.lt);
    t.reserve(3 * names.items.len);
    var r = rt.NIL;
    var i = names.items.len;
    while (i > 0) {
        i -= 1;
        r = t.cons(data.intern(names.items[i]), r);
    }
    return r;
}
pub const @"%%module-exports" = WN("%module-exports", moduleExports, 1, 1);

fn standinCode(t: *Thread) callconv(.c) void {
    return @call(.always_tail, rt.fail(t, "this procedure is only described (no value of it in a native program)", &.{}), .{t});
}

/// one stand-in per binding identity, so that eq? tells re-exports from
/// distinct bindings (as the JVM implementation's values do)
var standins: [lib.id_count]?Word = @splat(null);
var markers: [lib.id_count]u8 = @splat(0);

fn standin(e: lib.Export) Word {
    if (standins[e.id]) |w| return w;
    const w = switch (e.kind) {
        .syntax => blk: {
            const q = rt.staticAlloc(3, false);
            q[0] = rt.hdr(rt.T_NATIVE, 2);
            q[1] = @intFromEnum(sys.NativeKind.macro_standin);
            q[2] = @intFromPtr(&markers[e.id]);
            break :blk rt.tagPtr(q);
        },
        .procedure => rt.primitive(&standinCode, "described-procedure"),
        .value, .unknown => blk: {
            // a distinct object for each value: a static one-element vector
            const q = rt.staticAlloc(2, false);
            q[0] = rt.hdr(rt.T_VECTOR, 1);
            q[1] = rt.UNSPEC;
            break :blk rt.tagPtr(q);
        },
    };
    if (e.id != 0) standins[e.id] = w;
    return w;
}

fn moduleRef(t: *Thread) Err!Word {
    const l = try libraryArg(t, "%module-ref");
    const s = arg(t, 1);
    if (!data.isSymbol(s)) return P.argTypeError(t);
    const name = data.symbolName(s);
    for (l.exports) |e| if (std.mem.eql(u8, e.name, name)) return standin(e);
    return raise(t, std.fmt.allocPrint(pa, "{s} is not bound", .{name}) catch rt.oom(), &.{});
}
pub const @"%%module-ref" = WN("%module-ref", moduleRef, 2, 2);

// --- procedure-doc ---------------------------------------------------------------

/// docstrings of lambdas by their code (set by the modules' initialization)
var docs: std.AutoHashMapUnmanaged(usize, []const u8) = .empty;

pub fn setDoc(code: rt.Code, doc: []const u8) void {
    docs.put(pa, @intFromPtr(code), doc) catch rt.oom();
}

/// The text of a primitive (primitive_docs.zig is sorted by name)
fn primitiveDoc(name: []const u8) ?[]const u8 {
    const table = @import("primitive_docs.zig").docs;
    var lo: usize = 0;
    var hi: usize = table.len;
    while (lo < hi) {
        const mid = (lo + hi) / 2;
        switch (std.mem.order(u8, table[mid].name, name)) {
            .eq => return table[mid].doc,
            .lt => lo = mid + 1,
            .gt => hi = mid,
        }
    }
    return null;
}

/// The docstring of a procedure (a primitive's text as the JVM
/// implementation's), or #f
fn procedureDoc(t: *Thread) Err!Word {
    const p = arg(t, 0);
    if (!(rt.isPtr(p) and rt.objType(p) == rt.T_CLOSURE)) return rt.FALSE;
    const doc = if (rt.isPrimitive(p))
        primitiveDoc(data.symbolName(rt.ptr(p)[2])) orelse return rt.FALSE
    else
        docs.get(rt.ptr(p)[1]) orelse return rt.FALSE;
    t.reserve(data.stringWords(doc.len, true));
    return data.heapStringUtf8(t, doc);
}
pub const @"%procedure-doc" = WN("procedure-doc", procedureDoc, 1, 1);

// --- eval: the expander state, the globals, primitives by name -------------------

/// The expander state of a program that links eval (a datum's text, set by
/// the program's specials function)
var eval_state: ?[]const u8 = null;

pub fn setEvalState(s: []const u8) void {
    eval_state = s;
}

fn evalState(t: *Thread) Err!Word {
    const s = eval_state orelse return rt.FALSE;
    t.reserve(data.stringWords(s.len, true));
    return data.heapStringUtf8(t, s);
}
pub const @"%%eval-state" = WN("%eval-state", evalState, 0, 0);

/// The compiled program's global cells by name ("<module>: <variable>")
var global_index: std.StringHashMapUnmanaged(u32) = .empty;
var global_cells: std.ArrayList(struct { name: []const u8, cell: *Word }) = .empty;

pub fn registerGlobal(name: []const u8, cell: *Word) void {
    const r = global_index.getOrPut(pa, name) catch rt.oom();
    if (r.found_existing) return;
    r.value_ptr.* = @intCast(global_cells.items.len);
    global_cells.append(pa, .{ .name = name, .cell = cell }) catch rt.oom();
}

/// (%native-global name): the index of the program's cell of the global
/// named name, or #f if the program has none
fn nativeGlobal(t: *Thread) Err!Word {
    const name = data.toUtf8(try P.stringArg(t, 0));
    return if (global_index.get(name)) |i| rt.fix(i) else rt.FALSE;
}
pub const @"%%native-global" = WN("%native-global", nativeGlobal, 1, 1);

fn cellArg(t: *Thread) Err!usize {
    const i = arg(t, 0);
    if (!rt.isFix(i) or rt.unfix(i) < 0 or rt.unfix(i) >= global_cells.items.len)
        return raise(t, "%native-global-ref: bad global", &.{i});
    return @intCast(rt.unfix(i));
}

fn nativeGlobalRef(t: *Thread) Err!Word {
    const g = global_cells.items[try cellArg(t)];
    const v = g.cell.*;
    if (v == rt.UNBOUND) return raise(t, std.fmt.allocPrint(pa, "{s} is not bound", .{g.name}) catch rt.oom(), &.{});
    return v;
}
pub const @"%%native-global-ref" = WN("%native-global-ref", nativeGlobalRef, 1, 1);

fn nativeGlobalSet(t: *Thread) Err!Word {
    const g = global_cells.items[try cellArg(t)];
    // the program's global arrays are roots of every collection
    g.cell.* = arg(t, 1);
    return rt.UNSPEC;
}
pub const @"%%native-global-set!" = WN("%native-global-set!", nativeGlobalSet, 2, 2);

/// (%primitive-ref name): the procedure (or value) of the runtime's
/// primitive named name (a symbol), or #f
var prim_cache: std.StringHashMapUnmanaged(Word) = .empty;

fn primitiveRef(t: *Thread) Err!Word {
    const s = arg(t, 0);
    if (!rt.isPtr(s) or rt.objType(s) != rt.T_SYMBOL) return raise(t, "%primitive-ref: not a symbol", &.{s});
    const name = data.symbolName(s);
    if (prim_cache.get(name)) |w| return w;
    const table = @import("root").primitive_table;
    for (table) |e| {
        if (std.mem.eql(u8, e.name, name)) {
            // a value primitive's value may be a heap object: not cached
            if (e.make) |make| return make();
            const w = rt.primitive(e.code.?, e.name); // static
            prim_cache.put(pa, e.name, w) catch rt.oom();
            return w;
        }
    }
    return rt.FALSE;
}
pub const @"%%primitive-ref" = WN("%primitive-ref", primitiveRef, 1, 1);

// --- primitives over the expander at run time ------------------------------------

/// A primitive that (scm native eval) implements: calls its %eval-hook with
/// the primitive's name and the arguments. The driver links (scm native
/// eval) into a program that uses one.
fn evalHook(comptime op: []const u8) type {
    return struct {
        fn code(t: *Thread) callconv(.c) void {
            const h = t.special(.eval_hook) orelse
                return @call(.always_tail, rt.fail(t, "primitive not implemented in dabscm native:", &.{data.intern(op)}), .{t});
            t.ensureArgs(t.argc + 1);
            var i = t.argc;
            while (i > 0) : (i -= 1) t.args[i] = t.args[i - 1];
            t.args[0] = data.intern(op);
            t.argc += 1;
            return @call(.always_tail, rt.enter(t, h), .{t});
        }
    };
}
pub const @"%macroexpand": rt.Code = &evalHook("macroexpand").code;
pub const @"%bound?": rt.Code = &evalHook("bound?").code;
